"""Data transformation utilities."""

import functools
from typing import Any, Dict, List, Callable, Optional

_transforms: Dict[str, Callable] = {}


def get_transform(name: str) -> Optional[Callable]:
    """Get a transform by name."""
    return _transforms.get(name)


def compose(*transforms: Callable) -> Callable:
    """Compose multiple transforms together."""
    def composed(data: Any) -> Any:
        for transform in reversed(transforms):
            data = transform(data)
        return data
    return composed


def register(name: str, transform: Callable) -> None:
    """Register a transform by name."""
    _transforms[name] = transform


def identity(data: Any) -> Any:
    """Return data unchanged."""
    return data


def to_upper(data: Dict[str, Any]) -> Dict[str, Any]:
    """Convert all string values to uppercase."""
    if isinstance(data, dict):
        return {k: v.upper() if isinstance(v, str) else v for k, v in data.items()}
    return data


def to_lower(data: Dict[str, Any]) -> Dict[str, Any]:
    """Convert all string values to lowercase."""
    if isinstance(data, dict):
        return {k: v.lower() if isinstance(v, str) else v for k, v in data.items()}
    return data


def to_int(data: Dict[str, Any]) -> Dict[str, Any]:
    """Convert all numeric string values to int."""
    if isinstance(data, dict):
        return {k: int(v) if isinstance(v, str) and v.isdigit() else v for k, v in data.items()}
    return data


def to_float(data: Dict[str, Any]) -> Dict[str, Any]:
    """Convert all numeric string values to float."""
    if isinstance(data, dict):
        return {k: float(v) if isinstance(v, str) and v.replace('.', '').replace('-', '').isdigit() else v for k, v in data.items()}
    return data


def add_field(data: Dict[str, Any], field_name: str, value: Any) -> Dict[str, Any]:
    """Add a new field to the data."""
    result = data.copy() if isinstance(data, dict) else {}
    result[field_name] = value
    return result


def remove_field(data: Dict[str, Any], field_name: str) -> Dict[str, Any]:
    """Remove a field from the data."""
    result = data.copy() if isinstance(data, dict) else {}
    result.pop(field_name, None)
    return result


def rename_field(data: Dict[str, Any], old_name: str, new_name: str) -> Dict[str, Any]:
    """Rename a field in the data."""
    result = data.copy() if isinstance(data, dict) else {}
    if old_name in result:
        result[new_name] = result.pop(old_name)
    return result


def filter_fields(data: Dict[str, Any], keep: List[str]) -> Dict[str, Any]:
    """Keep only the specified fields."""
    result = {}
    for field in keep:
        if field in data:
            result[field] = data[field]
    return result


def transform_data(data: Dict[str, Any], transforms: List[str]) -> Dict[str, Any]:
    """Apply a list of transforms to the data."""
    for transform_name in transforms:
        transform = get_transform(transform_name)
        if transform:
            data = transform(data)
    return data


def build_pipeline(config: Dict[str, Any]) -> Optional[Callable]:
    """Build a transform pipeline from config."""
    transforms = config.get("transforms", [])
    pipeline = identity
    for transform_name in transforms:
        transform = get_transform(transform_name)
        if transform:
            pipeline = compose(pipeline, transform)
    return pipeline


def apply_transforms(data: Dict[str, Any], transforms: List[str]) -> Dict[str, Any]:
    """Apply transforms to data using a list of transform names."""
    pipeline = build_pipeline({"transforms": transforms})
    if pipeline:
        data = pipeline(data)
    return data
